import * as React from 'react';
import { cleanup, render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { Slot } from './slot';
import { afterEach, describe, it, vi, expect } from 'vitest';

// Reproduction for: installHook.js:1 Error: Maximum update depth exceeded - React 19 + Radix
//
// Mirrors the reported setup (Plate/Slate editor + Radix asChild components): the
// consumer's function ref triggers an update (e.g. editor onChange / onContextChange).
// Slot re-creates its composed ref on every render, so React detaches/reattaches the
// ref on every re-render, which re-invokes the ref callback, which schedules another
// update -> infinite loop -> "Maximum update depth exceeded".

const Input = React.forwardRef<
  React.ComponentRef<'input'>,
  React.ComponentProps<'input'> & { asChild?: boolean }
>(({ asChild, children, ...props }, forwardedRef) => {
  const Comp = asChild ? Slot : 'input';
  const [value, setValue] = React.useState('');
  return (
    <Comp
      {...props}
      onChange={(event) => setValue(event.target.value)}
      ref={forwardedRef}
      value={value}
    >
      {children}
    </Comp>
  );
});

describe('repro: maximum update depth exceeded', () => {
  afterEach(cleanup);

  it('does not loop when a ref callback schedules an update (asChild)', () => {
    const App = () => {
      const [tick, setTick] = React.useState(0);
      const handleRef = React.useCallback((node: HTMLInputElement | null) => {
        // like Slate/Plate: a ref change triggers an update
        setTick((t) => t + 1);
      }, []);
      void tick;
      return (
        <Input asChild ref={handleRef}>
          <input />
        </Input>
      );
    };
    expect(() => render(<App />)).not.toThrow();
    const input = screen.getByRole('textbox');
    expect(input).toBeTruthy();
  });

  it('does not re-invoke a stable function ref on unrelated re-renders (asChild)', async () => {
    const handleRef = vi.fn();
    render(
      <Input asChild ref={handleRef}>
        <input />
      </Input>,
    );
    await userEvent.type(screen.getByRole('textbox'), 'foo');
    expect(handleRef).toHaveBeenCalledTimes(1);
  });
});

